/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_histupd_to_wrongnote_once` AFTER UPDATE ON `history` FOR EACH ROW BEGIN

  IF NEW.is_correct = 0

     AND (OLD.is_correct IS NULL OR OLD.is_correct <> 0)

     AND NEW.quiz_id IS NOT NULL THEN

    INSERT IGNORE INTO wrong_note (user_id, wrong_quiz_id)

    VALUES (NEW.user_id, NEW.quiz_id);

  END IF;

END */;;
