/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `bi_options_uuid` BEFORE INSERT ON `options` FOR EACH ROW BEGIN
  IF NEW.`option_id` IS NULL OR NEW.`option_id`='' THEN SET NEW.`option_id`=UUID(); END IF;
END */;;
