--
-- Table structure for table `quiz`
--

DROP TABLE IF EXISTS `quiz`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz` (
  `quiz_id` varchar(36) NOT NULL COMMENT 'PK. 퀴즈 고유번호',
  `video_id` varchar(36) DEFAULT NULL COMMENT 'FK → video.video_id',
  `question_text` text COMMENT '문제 본문',
  `category_id` varchar(36) DEFAULT NULL COMMENT 'FK → category.category_id',
  PRIMARY KEY (`quiz_id`),
  KEY `video_id_idx` (`video_id`),
  KEY `category_id_idx` (`category_id`),
  CONSTRAINT `fk_quiz_category` FOREIGN KEY (`category_id`) REFERENCES `category` (`category_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_quiz_video` FOREIGN KEY (`video_id`) REFERENCES `video` (`video_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='퀴즈(문제) : 영상, 문제 본문, 상황 유형';
