INSERT INTO `quiz` VALUES ('110353_middle_0','middle_110353','다음은 한 운전자가 주행 중 경험한 실제 도로 상황이다. 다음 중 도로교통법상 **명백한 위반**에 해당하는 행동은 무엇인가?',NULL),('110353_middle_1','middle_110353','다음 중 공사 구간을 통행하는 운전자의 행위 중 도로교통법상 위법에 해당하는 것은 무엇인가?',NULL),('110353_middle_2','middle_110353','다음 중 도로교통법상 어린이 보호구역 내에서 올바른 주행 방법에 해당하는 것을 모두 고르시오.',NULL),('110353_middle_3','middle_110353','다음 중 적색으로 포장된 아스팔트 구간이 아닌 것은?',NULL),('110369_middle_0','middle_110369','영상을 보았을 때, 다음 중 올바른 조치로 옳은 것은?',NULL),('110371_basic_0','basic_110371','전방에 화물차가 앞서고 있어 차선이 막혔을 때, 운전자는 어떻게 행동해야 하나요?',NULL),('131062_hard_0','hard_131062','교차로에서 운전자 차량이 직진을 하고 있다. 교차로 전방 신호는 적색 점멸 신호(빨간불이 깜빡임)이다. 교차로 한가운데에서 운전자 차량과 검은색 차량이 부딪히는 사고가 발생한다. 해당 상황에서 사고를 피하려면 운전자가 어떤 행동을 했어야 하는가?',NULL),('131062_hard_1','hard_131062','교차로에서 좌/우회전하는 방법을 가장 바르게 설명한 것은?',NULL),('149112_hard_0','hard_149112','우회전 중 검은색 세단과 충돌한 경우, 충돌 방지 책임을 지는 운전자를 올바르게 기술한 것은?',NULL),('154060_basic_0','basic_154060','터널에 진입하면서 조명이 어두워지는 상황에서 운전자는 어떤 조치를 취해야 합니까?',NULL),('154060_basic_1','basic_154060','다음 중 앞지르기가 가능한 장소는?',NULL),('154060_basic_2','basic_154060','다음 중 터널을 통과할 때 운전자의 안전수칙으로 잘못된 것은?',NULL),('191130_hard_0','hard_191130','영상에서 운전자 차량이 우회전 후 녹색 신호에서 진행하던 중, 횡단보도를 건너는 보행자와 충돌했다. \r\n이 상황에 대한 올바른 법적 해석은 무엇인가?',NULL),('191130_hard_1','hard_191130','운전자가 신호등 없는 횡단보도에 접근했을 때, 보행자가 길을 건너려고 기다리고 있다면 운전자는 어떻게 해야 하는가?',NULL),('191130_hard_2','hard_191130','운전자가 우회전할 때 횡단보도에 보행자가 통행 중인 경우, 운전자의 옳은 조치는?',NULL),('192029_hard_0','hard_192029','해당 영상은 회전교차로 내의 차대차 충돌영상이다. 영상에 대한 설명으로 옳은 것은?',NULL),('192029_hard_1','hard_192029','도로의 원활한 소통과 안전을 위하여 회전교차로의 설치가 필요한 곳은?',NULL),('192029_hard_2','hard_192029','다음 중 회전교차로에서의 금지 행위인 것을 모두 고르시오.',NULL),('192029_hard_3','hard_192029','다음 중 회전교차로에서 통행 우선권이 보장된 회전차량은?',NULL),('87768_middle_0','middle_87768','다음 중 도로교통법에 따라 “전방 정체가 생겼을 때” Ego 차량이 정지할 수 있는 행위에 대한 설명으로 가장 적절한 것은?',NULL),('87769_middle_0','middle_87769','영상에서 주행 방향이 정해지지 않은 좁은 골목길에서 운전자 차량과 맞은편 차량이 마주쳤다. \n이때 운전자가 취해야 할 올바른 조치는 무엇인가?\n',NULL),('87769_middle_1','middle_87769','좁은 골목길에서 대형 버스와 승용차가 마주쳤다. 이때 교행이 곤란하다면 어떻게 해야 하는가?\n',NULL),('87769_middle_2','middle_87769','좁은 도로에서 마주 오는 차량과 교행할 수 없는 경우, 운전자가 가장 먼저 해야 할 올바른 행동은 무엇인가?',NULL),('87769_middle_3','middle_87769','교행이 곤란한 도로에서 마주 오는 차량이 서로 양보하지 않고 계속 진행한다면, 어떤 법 위반이 될 수 있는가?\n',NULL),('87785_middle_0','middle_87785','전진 중인 차량이 앞에 정지해 있는 SUV(스포츠 유틸리티 차량)를 마주할 때, 운전자는 무엇을 해야 하는가?',NULL),('87785_middle_1','middle_87785','도로교통법령상 차로에 따른 통행차의 기준에 대한 설명이다. 잘못된 것은?',NULL),('87785_middle_2','middle_87785','도로교통법령상 차로에 따른 통행구분 설명이다. 잘못된 것은?',NULL),('98453_basic_0','basic_98453','Ego 차량이 회전교차로에 진입할 때 가장 적절한 운전 행위는?',NULL),('98453_basic_1','basic_98453','다음 중 회전교차로를 통행 중인 운전자의 행동으로 적절한 것을 모두 고르시오.',NULL),('98453_basic_2','basic_98453','회전교차로 안에서 2차로로 주행 중이던 차량이 차선을 변경하려고 한다. 이때 올바른 방법은?',NULL),('busstop_hard_0','hard_busstop','영상과 같이 운전자 차량이 보행자와 충돌한 경우, 도로교통법상 위반에 해당하는 것은 무엇인가?',NULL),('left_green_right_red_basic_0','basic_left_green_right_red','영상에서의 운전자 차량의 주행에 대한 도로교통법상 옳은 판단은 무엇인가?',NULL),('left_green_right_red_basic_1','basic_left_green_right_red','교차로에서 좌회전할 때 가장 위험한 요인은?',NULL),('left_green_right_red_basic_2','basic_left_green_right_red','신호등이 없는 교차로에서의 옳은 것은?',NULL),('left_green_right_red_basic_3','basic_left_green_right_red','비보호좌회전 교차로에서 좌회전하고자 할 때의 설명으로 옳은 것을 모두 고르시오.',NULL),('zigzag_basic_0','basic_zigzag','이 영상에서 도로의 “지그재그” 노면표시는 무엇을 의미하는가?',NULL),('zigzag_basic_1','basic_zigzag','다음 중 노면표시에 대한 설명으로 옳은 것은 무엇인가?',NULL),('zigzag_basic_2','basic_zigzag','다음 설명 중 옳은 것을 모두 고르시오.',NULL);
