DROP TABLE IF EXISTS `wrong_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wrong_note` (
  `wrong_note_id` varchar(36) NOT NULL COMMENT 'PK. 오답 노트 고유번호',
  `user_id` varchar(36) NOT NULL COMMENT 'FK → users.user_id',
  `wrong_quiz_id` varchar(36) DEFAULT NULL COMMENT 'FK → quiz.quiz_id',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`wrong_note_id`),
  UNIQUE KEY `uq_wrong_note_user_quiz` (`user_id`,`wrong_quiz_id`),
  KEY `user_id_idx` (`user_id`),
  KEY `wrong_quiz_id_idx` (`wrong_quiz_id`),
  CONSTRAINT `fk_wn_quiz` FOREIGN KEY (`wrong_quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_wn_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='오답 노트';
/*!40101 SET character_set_client = @saved_cs_client */;

